        claim_amt = float(args.get("claim_amount_vnd", 0.0))
        is_sole = bool(args.get("sole_arbitrator", False))
        tribunal = ArbitrationTribunalType.SOLE_ARBITRATOR if is_sole else ArbitrationTribunalType.THREE_ARBITRATORS
